import os, sqlite3, shutil, datetime

profile_dir = os.path.expandvars(r'%LOCALAPPDATA%\hermes\profiles\flipping')
db_path = os.path.join(profile_dir, 'state.db')
backup_dir = os.path.join(profile_dir, 'desktop-backups')
os.makedirs(backup_dir, exist_ok=True)

ts = datetime.datetime.now().strftime('%Y%m%d_%H%M%S')
backup_path = os.path.join(backup_dir, f'state_backup_before_reset_{ts}.db')

if os.path.exists(db_path):
    shutil.copy2(db_path, backup_path)
    print(f'Backup created: {backup_path}')

    conn = sqlite3.connect(db_path)
    cur = conn.cursor()

    # Get initial counts
    tables_to_check = ['sessions', 'messages', 'session_model_usage', 'system_prompts']
    counts_before = {}
    for t in tables_to_check:
        try:
            cur.execute(f'SELECT COUNT(*) FROM {t}')
            counts_before[t] = cur.fetchone()[0]
        except sqlite3.OperationalError:
            counts_before[t] = 'N/A'
    print('Counts before:', counts_before)

    # Wipe
    for t in tables_to_check:
        try:
            cur.execute(f'DELETE FROM {t}')
        except sqlite3.OperationalError as e:
            print(f'Skip {t}: {e}')

    # Rebuild FTS5 safely
    for fts in ['messages_fts', 'messages_fts_trigram']:
        try:
            cur.execute(f\"INSERT INTO {fts}({fts}) VALUES('rebuild')\")
        except sqlite3.OperationalError as e:
            print(f'Skip fts {fts}: {e}')

    conn.commit()
    cur.execute('VACUUM')
    conn.commit()

    # Verify counts
    counts_after = {}
    for t in tables_to_check:
        try:
            cur.execute(f'SELECT COUNT(*) FROM {t}')
            counts_after[t] = cur.fetchone()[0]
        except sqlite3.OperationalError:
            counts_after[t] = 'N/A'
    print('Counts after:', counts_after)
    conn.close()
else:
    print('state.db does not exist')

# Purge request dumps
sessions_dir = os.path.join(profile_dir, 'sessions')
if os.path.exists(sessions_dir):
    dump_count = 0
    for f in os.listdir(sessions_dir):
        if f.startswith('request_dump_') and f.endswith('.json'):
            os.remove(os.path.join(sessions_dir, f))
            dump_count += 1
    print(f'Removed {dump_count} request dump files')
""}

